// Find nearest tile in a direction
int find_nearest(int r, int c, int dr, int dc) {
    r += dr;
    c += dc;
    while (r >= 0 && r < M && c >= 0 && c < N) {
        if (grid[r][c] != '.') return r * N + c;
        r += dr;
        c += dc;
    }
    return -1;
}

int main() {
