    int changed = 1;

    while (changed) {
        changed = 0;
        for (int r = 0; r < M; r++) {
            for (int c = 0; c < N; c++) {
                if (grid[r][c] != '.') continue; // must be empty cell to hit

                int up = find_nearest(r, c, -1, 0);
                int down = find_nearest(r, c, 1, 0);
                int left = find_nearest(r, c, 0, -1);
                int right = find_nearest(r, c, 0, 1);

                int tiles[4];
