#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXM 505
#define MAXN 505
#define MAXV 1005
#define INF 1000000000

typedef struct Edge {
    int to, cap, rev;
} Edge;

static Edge *g[MAXV];
static int gsz[MAXV], gcap[MAXV];
static int level_[MAXV], it_[MAXV];
static int q_[MAXV];

static void add_edge_directed(int fr, int to, int cap) {
    if (gsz[fr] >= gcap[fr]) {
        gcap[fr] = gcap[fr] ? gcap[fr] * 2 : 4;
        g[fr] = (Edge*)realloc(g[fr], gcap[fr] * sizeof(Edge));
    }
    if (gsz[to] >= gcap[to]) {
        gcap[to] = gcap[to] ? gcap[to] * 2 : 4;
        g[to] = (Edge*)realloc(g[to], gcap[to] * sizeof(Edge));
    }
    Edge a = {to, cap, gsz[to]};
    Edge b = {fr, 0,   gsz[fr]};
    g[fr][gsz[fr]++] = a;
    g[to][gsz[to]++] = b;
}

static int bfs(int s, int t, int V) {
    for (int i = 0; i < V; i++) level_[i] = -1;
    int head = 0, tail = 0;
    level_[s] = 0;
    q_[tail++] = s;
    while (head < tail) {
        int v = q_[head++];
        for (int i = 0; i < gsz[v]; i++) {
            Edge *e = &g[v][i];
            if (e->cap > 0 && level_[e->to] < 0) {
                level_[e->to] = level_[v] + 1;
                q_[tail++] = e->to;
            }
        }
    }
    return level_[t] >= 0;
}

static int dfs(int v, int t, int f) {
    if (v == t) return f;
    for (int *i = &it_[v]; *i < gsz[v]; (*i)++) {
        Edge *e = &g[v][*i];
        if (e->cap > 0 && level_[v] < level_[e->to]) {
            int d = dfs(e->to, t, f < e->cap ? f : e->cap);
            if (d > 0) {
                e->cap -= d;
                g[e->to][e->rev].cap += d;
                return d;
            }
        }
    }
    return 0;
}

static int maxflow(int s, int t, int V) {
    int flow = 0, f;
    while (bfs(s, t, V)) {
        for (int i = 0; i < V; i++) it_[i] = 0;
        while ((f = dfs(s, t, INF)) > 0) flow += f;
    }
    return flow;
}

static char board[MAXM][MAXN];
static int row1[26], col1[26], row2[26], col2[26], cnt[26];

int main(void) {
    int M, N;
    if (scanf("%d %d", &M, &N) != 2) return 0;

    for (int c = 0; c < 26; c++) {
        cnt[c] = 0;
        row1[c] = col1[c] = row2[c] = col2[c] = -1;
    }

    for (int i = 0; i < M; i++) {
        scanf("%s", board[i]);
        for (int j = 0; j < N; j++) {
            char ch = board[i][j];
            if ('A' <= ch && ch <= 'Z') {
                int k = ch - 'A';
                if (cnt[k] == 0) {
                    row1[k] = i; col1[k] = j;
                } else {
                    row2[k] = i; col2[k] = j;
                }
                cnt[k]++;
            }
        }
    }

    int leftId[26], rightId[26];
    int L = 0, R = 0;
    for (int c = 0; c < 26; c++) {
        if (cnt[c] == 2) {
            if (((row1[c] + col1[c]) & 1) == 0) leftId[c] = L++;
            else rightId[c] = R++;
        }
    }

    int S = L + R;
    int T = S + 1;
    int V = T + 1;

    for (int i = 0; i < V; i++) {
        g[i] = NULL;
        gsz[i] = gcap[i] = 0;
    }

    for (int c = 0; c < 26; c++) {
        if (cnt[c] != 2) continue;
        int r1 = row1[c], c1 = col1[c];
        int r2 = row2[c], c2 = col2[c];
        if (((r1 + c1) & 1) == 0) {
            int u = leftId[c];
            add_edge_directed(S, u, 1);

            int dr = r2 - r1;
            int dc = c2 - c1;
            if ((dr == 0 && (dc == 1 || dc == -1)) || (dc == 0 && (dr == 1 || dr == -1))) {
                // adjacent orthogonally => removable alone, no conflict edge needed
            } else {
                if (dr == 0) {
                    // same row, need one between them
                    if (abs(dc) == 2) {
                        int mr = r1, mc = (c1 + c2) / 2;
                        if (board[mr][mc] == '.') {
                            // removable
                        }
                    }
                } else if (dc == 0) {
                    // same column
                    if (abs(dr) == 2) {
                        int mr = (r1 + r2) / 2, mc = c1;
                        if (board[mr][mc] == '.') {
                            // removable
                        }
                    }
                } else if (abs(dr) == 1 && abs(dc) == 1) {
                    // diagonal: need one of the two corner cells empty
                    int ar = r1, ac = c2;
                    int br = r2, bc = c1;
                    char A = board[ar][ac];
                    char B = board[br][bc];

                    int aOcc = (A != '.');
                    int bOcc = (B != '.');

                    if (!aOcc || !bOcc) {
                        // removable
                    } else {
                        int ca = A - 'A';
                        int cb = B - 'A';
                        if (((row1[ca] + col1[ca]) & 1) == 0) {
                            add_edge_directed(leftId[ca], L + rightId[c], 1);
                        } else {
                            add_edge_directed(u, L + rightId[ca], 1);
                        }
                        if (ca != cb) {
                            if (((row1[cb] + col1[cb]) & 1) == 0) {
                                add_edge_directed(leftId[cb], L + rightId[c], 1);
                            } else {
                                add_edge_directed(u, L + rightId[cb], 1);
                            }
                        }
                    }
                }
            }
        }
    }

    for (int c = 0; c < 26; c++) {
        if (cnt[c] == 2 && ((row1[c] + col1[c]) & 1)) {
            add_edge_directed(L + rightId[c], T, 1);
        }
    }

    int matching = maxflow(S, T, V);
    int totalColors = 0;
    for (int c = 0; c < 26; c++) if (cnt[c] == 2) totalColors++;

    int answer = 2 * (totalColors - matching);
    printf("%d\n", answer);

    for (int i = 0; i < V; i++) free(g[i]);
    return 0;
}

