    }

    // For each column, precompute nearest tile above/below each cell
    vector<vector<int>> up(M, vector<int>(N, -1));
    vector<vector<int>> down(M, vector<int>(N, -1));

    for (int j = 0; j < N; j++) {
        int last = -1;
        for (int i = 0; i < M; i++) {
            if (grid[i][j] != '.') last = i;
            up[i][j] = last;
        }
        last = -1;
        for (int i = M - 1; i >= 0; i--) {
            if (grid[i][j] != '.') last = i;
            down[i][j] = last;
        }
    }

    // For each row, precompute nearest tile left/right of each cell
    vector<vector<int>> left(M, vector<int>(N, -1));
    vector<vector<int>> right(M, vector<int>(N, -1));

    for (int i = 0; i < M; i++) {
        int last = -1;
        for (int j = 0; j < N; j++) {
            if (grid[i][j] != '.') last = j;
            left[i][j] = last;
        }
        last = -1;
        for (int j = N - 1; j >= 0; j--) {
            if (grid[i][j] != '.') last = j;
            right[i][j] = last;
        }
    }

    // For each color, store its two positions
    unordered_map<char, vector<pair<int,int>>> pos;
    for (int i = 0; i < M; i++) {
        for (int j = 0; j < N; j++) {
            char c = grid[i][j];
            if (c != '.') {
                pos[c].push_back({i, j});
            }
        }
    }

    int ans = 0;

    // For each pair of same color, check if they can be removed together
    for (auto &p : pos) {
        char col = p.first;
        auto &v = p.second;
        if (v.size() != 2) continue;
        int r1 = v[0].first, c1 = v[0].second;
        int r2 = v[1].first, c2 = v[1].second;

        // Try each empty cell as hitting point
        for (int i = 0; i < M; i++) {
            for (int j = 0; j < N; j++) {
                if (grid[i][j] != '.') continue;

                // get focused tiles
                vector<pair<int,int>> focused;
                // up
                if (up[i][j] != -1) focused.push_back({up[i][j], j});
                // down
                if (down[i][j] != -1) focused.push_back({down[i][j], j});
                // left
                if (left[i][j] != -1) focused.push_back({i, left[i][j]});
                // right
                if (right[i][j] != -1) focused.push_back({i, right[i][j]});

                // count colors among focused
                unordered_map<char, int> cnt;
                for (auto &tile : focused) {
                    char cc = grid[tile.first][tile.second];
                    cnt[cc]++;
                }

                // check if this pair can be removed
                // they must be both focused and same color
                bool found = false;
                for (auto &tile : focused) {
                    if (tile.first == r1 && tile.second == c1) found = true;
                }
                if (!found) continue;
                found = false;
                for (auto &tile : focused) {
                    if (tile.first == r2 && tile.second == c2) found = true;
                }
                if (!found) continue;

                // If both are in focused, they will be removed together if same color
                // Actually condition: "Remove tiles of the same color that have been focused on."
                // So if both are same color and both focused, they get removed.
                ans = max(ans, 2);
            }
        }
    }

    // Also consider removing 4 tiles (two pairs of same color)
    // For each empty cell, check if we can get two pairs
    for (int i = 0; i < M; i++) {
        for (int j = 0; j < N; j++) {
            if (grid[i][j] != '.') continue;

            vector<pair<int,int>> focused;
            if (up[i][j] != -1) focused.push_back({up[i][j], j});
            if (down[i][j] != -1) focused.push_back({down[i][j], j});
            if (left[i][j] != -1) focused.push_back({i, left[i][j]});
            if (right[i][j] != -1) focused.push_back({i, right[i][j]});

            unordered_map<char, int> cnt;
            for (auto &tile : focused) {
                char cc = grid[tile.first][tile.second];
                cnt[cc]++;
            }
            int total = 0;
            for (auto &kv : cnt) {
                total += (kv.second / 2) * 2;
            }
            ans = max(ans, total);
        }
    }

    cout << ans << '\n';

    return 0;
}

