struct DSU {
    vector<int> p, sz;
    DSU(int n = 0) { init(n); }
    void init(int n) {
        p.resize(n);
        sz.assign(n, 1);
        iota(p.begin(), p.end(), 0);
    }
    int find(int x) {
        if (p[x] == x) return x;
        return p[x] = find(p[x]);
    }
    bool unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return false;
        if (sz[a] < sz[b]) swap(a, b);
        p[b] = a;
        sz[a] += sz[b];
        return true;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int M, N;
    cin >> M >> N;
    vector<string> g(M);
    for (int i = 0; i < M; ++i) cin >> g[i];

    const int K = 26;
    vector<vector<pair<int,int>>> pos(K);
    for (int i = 0; i < M; ++i) {
        for (int j = 0; j < N; ++j) {
            char c = g[i][j];
            if ('A' <= c && c <= 'Z') pos[c - 'A'].push_back({i, j});
        }
    }

    // Give each existing color an id.
    vector<int> idOf(K, -1);
    vector<int> colors;
    for (int c = 0; c < K; ++c) {
        if (!pos[c].empty()) {
            idOf[c] = (int)colors.size();
            colors.push_back(c);
        }
    }
    int C = (int)colors.size();
    if (C == 0) {
        cout << 0 << '\n';
        return 0;
    }

    // Build conflict graph:
    // two colors are connected if there exists an empty cell from which one tile
    // of each color can be focused simultaneously. Then they cannot both remain,
    // so in the "removable together" graph they are in conflict.
    vector< bitset<26> > conflict(K);

    // For each empty cell, collect distinct colors among nearest tiles in 4 dirs.
    for (int i = 0; i < M; ++i) {
        // nearest left/right tile color for each cell in row i
        vector<int> leftC(N, -1), rightC(N, -1);

        int last = -1;
        for (int j = 0; j < N; ++j) {
            if (g[i][j] != '.') last = g[i][j] - 'A';
            leftC[j] = last;
        }
        last = -1;
        for (int j = N - 1; j >= 0; --j) {
            if (g[i][j] != '.') last = g[i][j] - 'A';
            rightC[j] = last;
        }

        // We will compute up/down by direct column preprocessing outside this loop,
        // so do nothing here.
    }

    // Precompute nearest up/down tile color for every cell.
    vector<vector<int>> upC(M, vector<int>(N, -1)), downC(M, vector<int>(N, -1));
    for (int j = 0; j < N; ++j) {
        int last = -1;
        for (int i = 0; i < M; ++i) {
            if (g[i][j] != '.') last = g[i][j] - 'A';
            upC[i][j] = last;
        }
        last = -1;
        for (int i = M - 1; i >= 0; --i) {
            if (g[i][j] != '.') last = g[i][j] - 'A';
            downC[i][j] = last;
        }
    }

    for (int i = 0; i < M; ++i) {
        vector<int> leftC(N, -1), rightC(N, -1);
        int last = -1;
        for (int j = 0; j < N; ++j) {
            if (g[i][j] != '.') last = g[i][j] - 'A';
            leftC[j] = last;
        }
        last = -1;
        for (int j = N - 1; j >= 0; --j) {
            if (g[i][j] != '.') last = g[i][j] - 'A';
            rightC[j] = last;
        }

        for (int j = 0; j < N; ++j) {
            if (g[i][j] != '.') continue;

            bool present[26] = {};
            int arr[4] = {upC[i][j], downC[i][j], leftC[j], rightC[j]};
            for (int t = 0; t < 4; ++t) {
                int c = arr[t];
                if (c != -1) present[c] = true;
            }

            vector<int> seen;
            for (int c = 0; c < 26; ++c) if (present[c]) seen.push_back(c);

            int s = (int)seen.size();
            for (int a = 0; a < s; ++a) {
                for (int b = a + 1; b < s; ++b) {
                    int x = seen[a], y = seen[b];
                    conflict[x].set(y);
                    conflict[y].set(x);
                }
            }
        }
    }

    // We need maximum number of colors removable.
    // A set of colors is removable iff no conflicting pair is chosen together.
    // Since only 26 colors exist, solve maximum independent set in conflict graph
    // by meet-in-the-middle.

    vector<int> verts;
    for (int c = 0; c < 26; ++c) if (!pos[c].empty()) verts.push_back(c);
    int n = (int)verts.size();

    int n1 = n / 2, n2 = n - n1;
    vector<int> A(verts.begin(), verts.begin() + n1);
    vector<int> B(verts.begin() + n1, verts.end());

    vector<int> maskAtoA(n1, 0), maskBtoB(n2, 0), maskBtoA(n2, 0);
    for (int i = 0; i < n1; ++i) {
        int c = A[i];
        for (int j = 0; j < n1; ++j) {
            if (conflict[c].test(A[j])) maskAtoA[i] |= (1 << j);
        }
    }
    for (int i = 0; i < n2; ++i) {
        int c = B[i];
        for (int j = 0; j < n2; ++j) {
            if (conflict[c].test(B[j])) maskBtoB[i] |= (1 << j);
        }
        for (int j = 0; j < n1; ++j) {
            if (conflict[c].test(A[j])) maskBtoA[i] |= (1 << j);
        }
    }

    int SZ2 = 1 << n2;
    vector<int> best(SZ2, 0);
    vector<char> indep2(SZ2, 0);
    indep2[0] = 1;
    for (int mask = 1; mask < SZ2; ++mask) {
        int b = __builtin_ctz(mask);
        int pmask = mask ^ (1 << b);
        if (indep2[pmask] && (maskBtoB[b] & pmask) == 0) {
            indep2[mask] = 1;
            best[mask] = __builtin_popcount((unsigned)mask);
        }
    }
    for (int i = 0; i < n2; ++i) {
        for (int mask = 0; mask < SZ2; ++mask) {
            if (mask & (1 << i)) {
                best[mask] = max(best[mask], best[mask ^ (1 << i)]);
            }
        }
    }

    int ansColors = 0;
    int SZ1 = 1 << n1;
    vector<char> indep1(SZ1, 0);
    indep1[0] = 1;
    for (int mask = 0; mask < SZ1; ++mask) {
        if (!indep1[mask] && mask != 0) continue;
        if (mask != 0) {
            int cnt = __builtin_popcount((unsigned)mask);
            int forbiddenA = 0;
            for (int i = 0; i < n2; ++i) {
                if (maskBtoA[i] & mask) forbiddenA |= (1 << i);
            }
            int allowedB = ((1 << n2) - 1) ^ forbiddenA;
            ansColors = max(ansColors, cnt + best[allowedB]);
        } else {
            ansColors = max(ansColors, best[(1 << n2) - 1]);
        }

        int firstZero = -1;
        for (int i = 0; i < n1; ++i) {
            if (!(mask & (1 << i))) {
                firstZero = i;
                break;
            }
        }
        if (firstZero == -1) continue;
        for (int i = firstZero; i < n1; ++i) {
            if (mask & (1 << i)) continue;
            if ((maskAtoA[i] & mask) == 0) {
                indep1[mask | (1 << i)] = 1;
            }
        }
    }

    cout << ansColors * 2 << '\n';
    return 0;
}

