        // Build graph for matching: nodes are colors that have two tiles
        List<Integer>[] adj = new ArrayList[26];
        for (int i = 0; i < 26; i++) adj[i] = new ArrayList<>();

        for (int c = 0; c < 26; c++) {
            if (colorPositions[c].size() != 2) continue;
            int r1 = colorPositions[c].get(0)[0], c1 = colorPositions[c].get(0)[1];
            int r2 = colorPositions[c].get(1)[0], c2 = colorPositions[c].get(1)[1];
            for (int d = 0; d < 26; d++) {
