                int r3 = colorPositions[d].get(0)[0], c3 = colorPositions[d].get(0)[1];
                int r4 = colorPositions[d].get(1)[0], c4 = colorPositions[d].get(1)[1];
                if (canPair(r1, c1, r2, c2, r3, c3, r4, c4)) {
                    adj[c].add(d);
                }
            }
        }

        // Maximum matching (blossom algorithm not needed, bipartite via colors)
        // Actually we can also brute force since at most 26 colors
        boolean[] used = new boolean[26];
        int[] match = new int[26];
        Arrays.fill(match, -1);
        int result = 0;
        for (int i = 0; i < 26; i++) {
            if (colorPositions[i].size() == 2 && match[i] == -1) {
                Arrays.fill(used, false);
                if (dfs(i, adj, used, match)) {
                    result += 2;
                }
            }
        }
        System.out.println(result);
    }

    static boolean dfs(int u, List<Integer>[] adj, boolean[] used, int[] match) {
        for (int v : adj[u]) {
            if (!used[v]) {
                used[v] = true;
                if (match[v] == -1 || dfs(match[v], adj, used, match)) {
                    match[v] = u;
                    match[u] = v;
                    return true;
                }
            }
        }
        return false;
    }

    static boolean canPair(int r1, int c1, int r2, int c2, int r3, int c3, int r4, int c4) {
        // Check if there exists an empty cell that can "focus" both pairs
        for (int r = 0; r < M; r++) {
            for (int c = 0; c < N; c++) {
                if (grid[r][c] != '.') continue;
                // Check focusing for pair (r1,c1)-(r2,c2)
                int up1 = findUp(r, c), down1 = findDown(r, c), left1 = findLeft(r, c), right1 = findRight(r, c);
                Set<String> focused1 = new HashSet<>();
                if (up1 != null) focused1.add(up1[0]+","+up1[1]);
                if (down1 != null) focused1.add(down1[0]+","+down1[1]);
                if (left1 != null) focused1.add(left1[0]+","+left1[1]);
                if (right1 != null) focused1.add(right1[0]+","+right1[1]);
                boolean hasFirst = focused1.contains(r1+","+c1) && focused1.contains(r2+","+c2);

                int up2 = findUp(r, c), down2 = findDown(r, c), left2 = findLeft(r, c), right2 = findRight(r, c);
                Set<String> focused2 = new HashSet<>();
                if (up2 != null) focused2.add(up2[0]+","+up2[1]);
                if (down2 != null) focused2.add(down2[0]+","+down2[1]);
                if (left2 != null) focused2.add(left2[0]+","+left2[1]);
                if (right2 != null) focused2.add(right2[0]+","+right2[1]);
                boolean hasSecond = focused2.contains(r3+","+c3) && focused2.contains(r4+","+c4);

                if (hasFirst && hasSecond) return true;
            }
        }
        return false;
    }

    static int[] findUp(int r, int c) {
        for (int i = r-1; i >= 0; i--) {
            if (grid[i][c] != '.') return new int[]{i, c};
        }
        return null;
    }

    static int[] findDown(int r, int c) {
        for (int i = r+1; i < M; i++) {
            if (grid[i][c] != '.') return new int[]{i, c};
        }
        return null;
    }

    static int[] findLeft(int r, int c) {
        for (int j = c-1; j >= 0; j--) {
            if (grid[r][j] != '.') return new int[]{r, j};
        }
        return null;
    }

    static int[] findRight(int r, int c) {
        for (int j = c+1; j < N; j++) {
            if (grid[r][j] != '.') return new int[]{r, j};
        }
        return null;
    }
}

