public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            if (c == -1) return null;
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int M = fs.nextInt();
        int N = fs.nextInt();

        char[][] g = new char[M][N];
        int[] r1 = new int[26], c1 = new int[26], r2 = new int[26], c2 = new int[26], cnt = new int[26];
        Arrays.fill(r1, -1);
        Arrays.fill(r2, -1);

        for (int i = 0; i < M; i++) {
            String s = fs.next();
            for (int j = 0; j < N; j++) {
                char ch = s.charAt(j);
                g[i][j] = ch;
                if (ch != '.') {
                    int x = ch - 'A';
                    if (cnt[x] == 0) {
                        r1[x] = i;
                        c1[x] = j;
                    } else {
                        r2[x] = i;
                        c2[x] = j;
                    }
                    cnt[x]++;
                }
            }
        }

        // Build row/column tile positions
        ArrayList<Integer>[] rowCols = new ArrayList[M];
        ArrayList<Integer>[] colRows = new ArrayList[N];
        for (int i = 0; i < M; i++) rowCols[i] = new ArrayList<>();
        for (int j = 0; j < N; j++) colRows[j] = new ArrayList<>();

        for (int i = 0; i < M; i++) {
            for (int j = 0; j < N; j++) {
                if (g[i][j] != '.') {
                    rowCols[i].add(j);
                    colRows[j].add(i);
                }
            }
        }

        int ans = 0;

        for (int color = 0; color < 26; color++) {
            if (cnt[color] != 2) continue;

            int a = r1[color], b = c1[color];
            int c = r2[color], d = c2[color];

            boolean removable = false;

            // Same row: need some empty cell on that row strictly between columns,
            // and no other tile between them on that row.
            if (a == c) {
                int row = a;
                int left = Math.min(b, d), right = Math.max(b, d);
                if (right - left >= 2) {
                    ArrayList<Integer> list = rowCols[row];
                    int idxL = Collections.binarySearch(list, left);
                    int idxR = Collections.binarySearch(list, right);
                    if (idxL >= 0 && idxR >= 0 && idxR == idxL + 1) {
                        removable = true;
                    }
                }
            }

            // Same column: analogous.
            if (!removable && b == d) {
                int col = b;
                int top = Math.min(a, c), bottom = Math.max(a, c);
                if (bottom - top >= 2) {
                    ArrayList<Integer> list = colRows[col];
                    int idxT = Collections.binarySearch(list, top);
                    int idxB = Collections.binarySearch(list, bottom);
                    if (idxT >= 0 && idxB >= 0 && idxB == idxT + 1) {
                        removable = true;
                    }
                }
            }

            // Rectangle case:
            // Need an empty cell (x,y) such that horizontally nearest tiles are exactly the pair
            // and vertically nearest tiles are exactly the pair.
            // This is possible iff:
            // - rows a,c are consecutive tile-rows in column y for y in overlap of horizontal visibility intervals
            // - cols b,d are consecutive tile-cols in row x for x in overlap of vertical visibility intervals
            // We test the 4 possible corner-induced candidate regions.

            if (!removable && a != c && b != d) {
                int top = Math.min(a, c), bottom = Math.max(a, c);
                int leftCol = (a < c) ? b : d;   // column of top occurrence? not directly needed
                // compute row interval where in row x, nearest left/right can be b and d
                // For rows x between the two rows? no, x is row of hit cell, and left/right depend only on row x.
                // Thus x must be a row where columns b and d are consecutive tiles in that row, impossible unless both tiles are on same row.
                // Therefore horizontal pair can only come from same row, vertical pair only from same column.
                // Since each color appears only twice, a pair can be removed only if the two tiles are aligned.
            }

            if (removable) ans += 2;
        }

        System.out.println(ans);
