    # Positions of each color (each appears 0 or 2 times)
    pos = defaultdict(list)
    for i in range(M):
        row = grid[i]
        for j, ch in enumerate(row):
            if ch != '.':
                pos[ch].append((i, j))

    # Build bipartite graph:
    # left side = rows [0..M-1]
    # right side = columns [0..N-1]
    # each color pair gives one edge between the two "line nodes" that can remove it.
    #
    # If the two tiles are on the same row, they can be removed by hitting some empty cell
    # on that row between them -> edge row-r to row-r (self-loop on row side).
    #
    # If on same column, similarly -> edge col-c to col-c (self-loop on column side).
    #
    # Otherwise, only possible if one of the rectangle corners is empty:
    # (r1,c2) or (r2,c1). Then hitting that empty corner focuses exactly those two tiles
    # among their directions, so edge row-ri to col-cj.
    #
    # Maximum removable pairs = maximum matching in this bipartite graph,
    # where self-loops simply mean that vertex alone can be used to take that edge.
    #
    # We preprocess:
    # - row_self[r] = whether row vertex r has a self-loop
    # - col_self[c] = whether col vertex c has a self-loop
    # - adj[row] = list of columns for normal edges

    row_self = [False] * M
    col_self = [False] * N
    adj = [[] for _ in range(M)]

    for ch, ps in pos.items():
        (r1, c1), (r2, c2) = ps
        if r1 == r2:
            # Need an empty cell strictly between them on the row
            a, b = sorted((c1, c2))
            ok = False
            for c in range(a + 1, b):
                if grid[r1][c] == '.':
                    ok = True
                    break
            if ok:
                row_self[r1] = True
        elif c1 == c2:
            # Need an empty cell strictly between them on the column
            a, b = sorted((r1, r2))
            ok = False
            for r in range(a + 1, b):
                if grid[r][c1] == '.':
                    ok = True
                    break
            if ok:
                col_self[c1] = True
        else:
            ok = False
            if grid[r1][c2] == '.':
                ok = True
            if grid[r2][c1] == '.':
                ok = True
            if ok:
                # Either corner works; in either case this pair consumes one row and one column.
                # Add one representative edge.
                adj[r1].append(c2)
                adj[r2].append(c1)

    # Maximum matching on normal row-column edges with Hopcroft-Karp
    INF = 10**18
    pairU = [-1] * M
    pairV = [-1] * N
    dist = [0] * M

    from collections import deque

    def bfs():
        q = deque()
        for u in range(M):
            if pairU[u] == -1:
                dist[u] = 0
                q.append(u)
            else:
                dist[u] = -1
        found = False
        while q:
            u = q.popleft()
            for v in adj[u]:
                pu = pairV[v]
                if pu == -1:
                    found = True
                elif dist[pu] == -1:
                    dist[pu] = dist[u] + 1
                    q.append(pu)
        return found

    def dfs(u):
        for v in adj[u]:
            pu = pairV[v]
            if pu == -1 or (dist[pu] == dist[u] + 1 and dfs(pu)):
                pairU[u] = v
                pairV[v] = u
                return True
        dist[u] = -1
        return False

    match = 0
    while bfs():
        for u in range(M):
            if pairU[u] == -1 and dfs(u):
                match += 1

    # After taking maximum row-column matches, we can still take self-loops
    # on unmatched row/column vertices.
    for r in range(M):
        if pairU[r] == -1 and row_self[r]:
            match += 1
    for c in range(N):
        if pairV[c] == -1 and col_self[c]:
            match += 1

    print(match * 2)

